14	        str = "MEDIA_EVENT_STOPPED";
15	    } else if (event == MEDIA_EVENT_COMPLETED) {
16	        str = "MEDIA_EVENT_COMPLETED";
17	    } else if (event == MEDIA_EVENT_PREPARED) {
18	        str = "MEDIA_EVENT_PREPARED";
19	    } else if (event == MEDIA_EVENT_PAUSED) {
20	        str = "MEDIA_EVENT_PAUSED";
21	    } else if (event == MEDIA_EVENT_SEEKED) {
22	        str = "MEDIA_EVENT_SEEKED";
23	    } else {
24	        str = "UNKNOW EVENT";
