30	static void media_test_controllee_music_callback(void *cookie, int event,
31	    int ret, const char *extra)
32	{
33	    struct audio_state *priv = (struct audio_state *)cookie;
34	
35	    syslog(LOG_INFO, "[%s][%d], event:%s(%d) ret:%d extra:%s\n", __func__, __LINE__, media_event_get_name(event), event, ret, extra);
36	
37	    /* Handle control message by mediatool api. */
38	    switch (event) {
39	    case MEDIA_EVENT_START:
40	        ret = media_player_start(priv->player);
41	        break;
42	
43	    case MEDIA_EVENT_PAUSE:
44	        ret = media_player_pause(priv->player);
45	        break;
46	
47	    case MEDIA_EVENT_STOP:
48	        ret = media_player_stop(priv->player);
49	        break;
50	
51	    case MEDIA_EVENT_INCREASE_VOLUME:
52	        ret = media_policy_increase_stream_volume(MEDIA_STREAM_MUSIC);
53	        break;
54	
55	    case MEDIA_EVENT_DECREASE_VOLUME:
56	        ret = media_policy_decrease_stream_volume(MEDIA_STREAM_MUSIC);
57	        break;
58	
59	    default:
60	        /* There is no song list in this demo. */
61	        ret = -ENOSYS;
62	        break;
63	    }
64	
65	    /* XXX: Another implemention for some status control message,
66	     * notify after received corresponding event from player's event callback */
67	    media_session_notify(priv->controlee, event, ret, NULL);
68	}
