70	int check_audio_position(void *handle)
71	{
72	    void *player = handle;
73	    int flag = 1;
74	    int times = 0;
75	    unsigned int position = 0, last_positon = 0;
76	
77	    while (times < CHECK_POSTION_TIMES) {
78	        media_player_get_position(player, &position);
79	        if (position - last_positon < CHECK_POSTION_INTERVAL / 2 / 1000) {
80	            flag = 0;
81	        }
82	        usleep(CHECK_POSTION_INTERVAL);
83	        times++;
84	        last_positon = position;
85	    }
86	
87	    syslog(LOG_INFO, "[%s][%d], position:%d flag=%d\n", __func__, __LINE__, position, flag);
88	    return flag;
89	}
