91	int test_session_common_setup(FAR void **state)
92	{
93	    int ret;
94	    struct audio_state *priv;
95	    if (*state)
96	        priv = *state;
97	    else {
98	        priv = malloc(sizeof(struct audio_state));
99	        if (!priv)
100	            return -ENOMEM;
