126	
127	    ret = media_player_start(priv->player);
128	    if (ret < 0) {
129	        syslog(LOG_ERR, "Player: start failed.\n");
130	        goto fail;
131	    }
132	
133	    if (!*state)
134	        *state = priv;
135	
136	    sleep(1);
137	
138	    if (check_audio_position(priv->player)) {
