60	static void media_event_cb(void* cookie, media_parcel* msg)
61	{
62	    MediaSessionPriv* priv = cookie;
63	    const char* extra;
64	    int32_t event;
65	    int32_t ret;
66	
67	    media_parcel_read_scanf(msg, "%i%i%s", &event, &ret, &extra);
68	    if (event == MEDIA_EVENT_CHANGED) {
69	        media_metadata_reinit(&priv->data);
70	        priv->need_query = true;
71	    } else if (event == MEDIA_EVENT_UPDATED)
72	        priv->need_query = true;
73	
74	    if (priv->event)
75	        priv->event(priv->cookie, event, ret, extra);
76	}
