82	void* media_session_open(const char* params)
83	{
84	    MediaSessionPriv* priv;
85	
86	    priv = calloc(1, sizeof(MediaSessionPriv));
87	    if (!priv)
88	        return NULL;
89	
90	    if (media_proxy(MEDIA_ID_SESSION, priv, NULL, "open", params, 0, NULL, 0) < 0)
91	        goto err;
92	
93	    media_metadata_init(&priv->data);
94	    media_proxy_set_release_cb(priv->proxy, media_release_cb, priv);
95	    priv->need_query = true;
96	    return priv;
97	
98	err:
99	    media_release_cb(priv);
100	    return NULL;
101	}
