446	        media_proxy_detach_release(priv->proxy);
447	        media_proxy_disconnect(priv->proxy);
448	        free(priv->cpu);
449	        priv->proxy = NULL;
450	        priv->cpu = NULL;
451	    }
452	
453	    /* Auto-reconnect: only SESSION reconnects; FOCUS is transient */
454	    if (!priv->proxy) {
455	        priv->proxy = media_proxy_connect(want);
456	        if (!priv->proxy) {
457	            pthread_mutex_unlock(&priv->offload_lock);
458	            return -ENOTCONN;
459	        }
460	        priv->cpu = strdup(want);
461	
462	        /* Replay init command (open/register/ping) */
463	        if (priv->init_cmd) {
