479	                priv->proxy = NULL;
480	                priv->cpu = NULL;
481	                pthread_mutex_unlock(&priv->offload_lock);
482	                return -ENOTCONN;
483	            }
484	        }
485	
486	        /* Rebuild notify channel */
487	        if (priv->event_cb_func) {
488	            media_proxy_set_event_cb(priv->proxy, priv->cpu,
489	                priv->event_cb_func, priv->event_cb_cookie);
490	        }
491	
492	        /* Rebind the owner destructor to the new transport (it was detached
