512	    switch (priv->type) {
513	    case MEDIA_ID_FOCUS:
514	        ret = media_parcel_append_printf(&in, "%i%s%s%s%i", priv->type,
515	            target, cmd, "", res_len);
516	        break;
517	
518	    case MEDIA_ID_GRAPH:
519	        ret = media_parcel_append_printf(&in, "%i%s%s%s%i", priv->type,
520	            target, cmd, arg, res_len);
521	        break;
522	
523	    case MEDIA_ID_POLICY:
524	        ret = media_parcel_append_printf(&in, "%i%s%s%s%i%i", priv->type,
525	            target, cmd, arg, apply, res_len);
526	        break;
527	
528	    case MEDIA_ID_PLAYER:
529	        ret = media_parcel_append_printf(&in, "%i%s%s%s%i", priv->type,
530	            target, cmd, arg, res_len);
531	        break;
532	
533	    case MEDIA_ID_RECORDER:
534	        ret = media_parcel_append_printf(&in, "%i%s%s%s%i", priv->type,
535	            target, cmd, arg, res_len);
536	        break;
537	
538	    case MEDIA_ID_SESSION:
539	        ret = media_parcel_append_printf(&in, "%i%s%s%s%i", priv->type,
540	            target, cmd, arg, res_len);
541	        break;
542	
543	    case MEDIA_ID_TRIGGER:
544	        ret = media_parcel_append_printf(&in, "%i%s%s%i%i", priv->type,
545	            cmd, arg, apply, res_len);
546	        if (ret < 0)
547	            goto out;
548	
549	        if (target)
550	            ret = media_parcel_append(&in, target, apply);
551	        break;
552	
553	    default:
554	        goto out;
555	    }
556	
557	    if (ret < 0)
558	        goto out;
559	
560	    ret = media_proxy_send_with_ack(priv->proxy, &in, &out);
561	#ifdef CONFIG_MEDIA_OFFLOAD_SERVICE
562	    if ((ret == -EPIPE || ret == -ECONNRESET)
563	        && priv->type == MEDIA_ID_SESSION && priv->offload_registered) {
564	        pthread_mutex_lock(&priv->offload_lock);
565	        media_proxy_detach_release(priv->proxy);
566	        media_proxy_disconnect(priv->proxy);
567	        free(priv->cpu);
568	        priv->proxy = NULL;
569	        priv->cpu = NULL;
570	        pthread_mutex_unlock(&priv->offload_lock);
571	        goto out;
572	    }
573	#endif
574	    if (ret < 0)
575	        goto out;
576	
577	    ret = media_parcel_read_scanf(&out, "%i%s", &resp, &response);
578	    if (ret < 0 || resp < 0)
579	        goto out;
580	
581	    if (res_len > 0 && response)
582	        strlcpy(res, response, res_len);
583	
584	out:
585	    /* log before deinit frees the parcel buffer */
586	    MEDIA_INFO("%s:%s:%p %s %s %s %s ret:%d resp:%d response:%s\n",
587	        media_id_get_name(priv->type), priv->cpu, (void*)(uintptr_t)priv, target ? target : "_",
588	        cmd, arg ? arg : "_", apply ? "apply" : "_", ret, (int)resp, response ? response : "_");
589	
590	    media_parcel_deinit(&in);
591	    media_parcel_deinit(&out);
592	
593	    return ret < 0 ? ret : resp;
594	}
595	
596	int media_proxy(int id, void* handle, const char* target, const char* cmd,
597	    const char* arg, int apply, char* res, int res_len)
598	{
599	    MediaProxyPriv *priv, priv_ = { 0 };
600	    char *saveptr, *cpu;
601	    int ret = -ENOSYS;
602	    char tmp[128];
603	
604	    priv = handle ? handle : &priv_;
605	    priv->type = id;
606	
607	    if (priv->proxy)
608	        return media_proxy_once(priv, target, cmd, arg, apply, res, res_len);
609	
610	    strlcpy(tmp, media_get_cpuname_by_type(priv->type), sizeof(tmp));
611	    for (cpu = strtok_r(tmp, " ,;|", &saveptr); cpu;
612	         cpu = strtok_r(NULL, " ,;|", &saveptr)) {
613	        priv->proxy = media_proxy_connect(cpu);
614	        if (!priv->proxy)
615	            continue;
616	
617	        priv->cpu = cpu;
618	        ret = media_proxy_once(priv, target, cmd, arg, apply, res, res_len);
619	
620	        /* keep the connection in need. */
621	        if (handle && ret >= 0) {
622	            priv->cpu = strdup(cpu);
623	            assert(priv->cpu);
624	#ifdef CONFIG_MEDIA_OFFLOAD_SERVICE
625	            if (priv->type == MEDIA_ID_SESSION) {
626	                pthread_mutex_init(&priv->offload_lock, NULL);
627	                priv->offload_registered = 1;
628	                priv->init_target = target ? strdup(target) : NULL;
629	                priv->init_cmd = cmd ? strdup(cmd) : NULL;
630	                priv->init_arg = arg ? strdup(arg) : NULL;
631	            }
632	#endif
633	            return ret;
634	        }
635	
636	        media_proxy_disconnect(priv->proxy);
637	
638	        /* Single connection Execution successful, break immediately.*/
639	        if (ret >= 0)
640	            break;
641	    }
642	
643	    priv->proxy = NULL;
644	    priv->cpu = NULL;
645	    return ret;
646	}
647	
648	void media_default_release_cb(void* handle)
649	{
650	    MediaProxyPriv* priv = handle;
651	
652	    free(priv->cpu);
653	    free(priv);
654	}
