98	        free(priv->loop);
99	        priv->loop = NULL;
100	    }
101	
102	    if (priv->str_val)
103	        free(priv->str_val);
104	
105	    pthread_mutex_destroy(priv->mutex);
106	    pthread_cond_destroy(priv->cond);
107	    free(priv->mutex);
108	    free(priv->cond);
109	    free(priv);
110	    *priv_p = NULL;
111	}
