141	    if (ret < 0) {
142	        syslog(LOG_INFO, "uv_async_queue_init failed %d\n", ret);
143	        return NULL;
144	    }
145	        
146	    pthread_mutex_lock(priv->mutex);
147	    priv->uv_running = true;
148	    pthread_cond_signal(priv->cond);
149	    pthread_mutex_unlock(priv->mutex);
150	
151	    while (priv->uv_running) {
152	        ret = uv_run(priv->loop, UV_RUN_DEFAULT);
153	        if (ret == 0)
154	            break;
155	    }
156	
157	    pthread_mutex_lock(priv->mutex);
158	    priv->uv_running = false;
159	    pthread_cond_signal(priv->cond);
160	    pthread_mutex_unlock(priv->mutex);
161	    syslog(LOG_INFO, "uvloop stop run:%d\n", ret);
