199	int policy_uv_setup(FAR void** state)
200	{
201	    uvpolicy_priv_s* priv = policy_uv_init();
202	    assert_non_null(priv);
203	
204	    pthread_attr_t attr;
205	    pthread_attr_init(&attr);
206	    pthread_attr_setstacksize(&attr, 80 * 1024);
207	    pthread_create(&priv->thread, &attr, policy_uvloop_thread, priv);
208	
209	    pthread_mutex_lock(priv->mutex);
210	    while (!priv->uv_running) {
211	        pthread_cond_wait(priv->cond, priv->mutex);
212	    }
213	    pthread_mutex_unlock(priv->mutex);
214	
215	    *state = priv;
216	    return 0;
217	}
