243	void policy_uv_wait_callback(uvpolicy_priv_s* priv)
244	{
245	    struct timespec ts;
246	    clock_gettime(CLOCK_REALTIME, &ts);
247	    ts.tv_sec += API_TIMEOUT / 1000;
248	    ts.tv_nsec += (API_TIMEOUT % 1000) * 1000000;
249	    ts.tv_sec += ts.tv_nsec / 1000000000;
250	    ts.tv_nsec %= 1000000000;
251	
252	    if (pthread_cond_timedwait(priv->cond, priv->mutex, &ts) == ETIMEDOUT) {
253	        pthread_mutex_unlock(priv->mutex);
254	        syslog(LOG_ERR, "pthread_cond_timedwait: wait_cb timeout\n");
255	        assert_true(0);
256	    }
257	}

