16	static uvpolicy_priv_s* policy_uv_init(void)
17	{
18	    uvpolicy_priv_s* priv = malloc(sizeof(*priv));
19	    if (!priv)
20	        return NULL;
21	    memset(priv, 0, sizeof(*priv));
22	
23	    priv->uv_running = false;
24	
25	    priv->loop = (uv_loop_t*)malloc(sizeof(uv_loop_t));
26	    if (!priv->loop) {
27	        syslog(LOG_INFO, "malloc failed %d\n", -errno);
28	        goto fail;
29	    }
30	
31	    if (uv_loop_init(priv->loop) < 0) {
32	        free(priv->loop);
33	        priv->loop = NULL;
34	        goto fail;
35	    }
36	
37	    priv->mutex = (pthread_mutex_t*)malloc(sizeof(pthread_mutex_t));
38	    if (!priv->mutex)
39	        goto fail;
40	    pthread_mutex_init(priv->mutex, NULL);
41	
42	    priv->cond = (pthread_cond_t*)malloc(sizeof(pthread_cond_t));
43	    if (!priv->cond) {
44	        free(priv->mutex);
45	        priv->mutex = NULL;
46	        goto fail;
47	    }
48	    pthread_cond_init(priv->cond, NULL);
49	
50	    return priv;
51	
52	fail:
53	    if (priv->loop) {
54	        /* priv->loop is guaranteed initialized here (uv_loop_init failure
55	         * frees and NULLs it before jumping). EBUSY would mean a handle
56	         * residue — assert so init-failure cleanup does not hide a leak.
57	         */
58	        assert_int_equal(uv_loop_close(priv->loop), 0);
59	        free(priv->loop);
60	        priv->loop = NULL;
61	    }
62	    free(priv);
63	    return NULL;
64	}
