66	static void policy_uv_on_close(uv_handle_t *handle)
67	{
68	    syslog(LOG_INFO, "Handle closed: %p", handle);
69	    handle->data = NULL;
70	}
71	// 关闭所有活动句柄的回调函数
72	static void policy_uv_close_active_handle(uv_handle_t *handle, void *arg)
73	{
74	    if (uv_is_active(handle)&& !uv_is_closing(handle)) {
75	        uv_close(handle, policy_uv_on_close);
76	    }
77	}
