79	static void policy_uv_deinit(uvpolicy_priv_s** priv_p)
80	{
81	    uvpolicy_priv_s* priv;
82	    if (!priv_p || !*priv_p) {
83	        syslog(LOG_INFO, "policy_uv_deinit: priv is NULL\n");
84	        return;
85	    }
86	    priv = *priv_p;
87	
88	    if (priv->loop) {
89	        // 使用 uv_walk 关闭所有活动句柄
90	        uv_walk(priv->loop, policy_uv_close_active_handle, NULL);
91	
92	        // 确保所有句柄都已关闭
93	        while (uv_loop_alive(priv->loop)) {
94	            uv_run(priv->loop, UV_RUN_NOWAIT);
95	        }
96	        // 关闭 UV 循环 — EBUSY 表示仍有未关闭 handle（UV 残留泄漏），断言 fail
97	        assert_int_equal(uv_loop_close(priv->loop), 0);
98	        free(priv->loop);
99	        priv->loop = NULL;
100	    }
101	
102	    if (priv->str_val)
103	        free(priv->str_val);
104	
105	    pthread_mutex_destroy(priv->mutex);
106	    pthread_cond_destroy(priv->cond);
107	    free(priv->mutex);
108	    free(priv->cond);
109	    free(priv);
110	    *priv_p = NULL;
111	}
